       (MW^2*(MW^2 - MZ^2)*(-1 + \[Xi]w)^2*(MW^2 - MZ^2*\[Xi]z)) - 
      (\[Xi]w^2*sorttad[{MW, MW*Sqrt[\[Xi]w], MW*Sqrt[\[Xi]w]}, {1, 1, 1}])/
       (MW^2*(MW^2 - MZ^2)*(-1 + \[Xi]w)^2*(MW^2 - MZ^2*\[Xi]z)) - 
      (MW^2*\[Xi]w^2*sorttad[{MZ, MW*Sqrt[\[Xi]w], MW}, {1, 1, 1}])/
       (MZ^4*(-MW^2 + MZ^2)*(-1 + \[Xi]w)*(-MZ^2 + MW^2*\[Xi]w)*
        (-1 + \[Xi]z)) + (MW^2*\[Xi]w^2*sorttad[{MZ, MW*Sqrt[\[Xi]w], 
          MW*Sqrt[\[Xi]w]}, {1, 1, 1}])/(MZ^4*(-MW^2 + MZ^2)*(-1 + \[Xi]w)*
        (-MZ^2 + MW^2*\[Xi]w)*(-1 + \[Xi]z)) - 
      (\[Xi]w*sorttad[{MW*Sqrt[\[Xi]w], MW*Sqrt[\[Xi]w], MW}, {1, 1, 1}])/
       (MW^2*(-1 + \[Xi]w)^2*(-MZ^2 + MW^2*\[Xi]w)*(MW^2*\[Xi]w - 
         MZ^2*\[Xi]z)) + (\[Xi]w*sorttad[{MW*Sqrt[\[Xi]w], MW*Sqrt[\[Xi]w], 
          MW*Sqrt[\[Xi]w]}, {1, 1, 1}])/(MW^2*(-1 + \[Xi]w)^2*
        (-MZ^2 + MW^2*\[Xi]w)*(MW^2*\[Xi]w - MZ^2*\[Xi]z)) + 
      (MW^2*\[Xi]w^2*sorttad[{MZ*Sqrt[\[Xi]z], MW*Sqrt[\[Xi]w], MW}, 
         {1, 1, 1}])/(MZ^4*(-1 + \[Xi]w)*(-1 + \[Xi]z)*\[Xi]z*
        (MW^2*\[Xi]w - MZ^2*\[Xi]z)*(-MW^2 + MZ^2*\[Xi]z)) - 
      (MW^2*\[Xi]w^2*sorttad[{MZ*Sqrt[\[Xi]z], MW*Sqrt[\[Xi]w], 
          MW*Sqrt[\[Xi]w]}, {1, 1, 1}])/(MZ^4*(-1 + \[Xi]w)*(-1 + \[Xi]z)*
        \[Xi]z*(MW^2*\[Xi]w - MZ^2*\[Xi]z)*(-MW^2 + MZ^2*\[Xi]z))))/
    (4096*cw^2*d*Pi^8*sw^2))
